using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.Rendering;
public static class NurseAnatomyRender {
 const string Output="C:/Program Files (x86)/Steam/steamapps/common/7 Days To Die/Mods/zzz_REBIRTH__3_0/Tools/EntityStudio/out/NurseAnatomyFit/Nurse_Moe_Fitted.png";
 public static void Run(){RenderOnly();NurseAnatomyAudit.Run();} public static void RenderOnly(){Render(false,false,"FrontRest");Render(true,false,"FrontAPose");Render(true,true,"SideAPose");}
 static void Render(bool pose,bool side,string label){try{EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Single);var nurse=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>(RebirthEntityStudio.RebirthNurseNativeAssembly.Folder+"/RebirthNurse_Authoring.prefab"));nurse.name="RebirthNurse";var moe=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>("Assets/NativeReferences/Moe/PrefabInstance/ZMoe.prefab"));moe.transform.position=Vector3.right*1.5f;RebirthEntityStudio.RebirthNurseNativeShaderPreview.Bind(nurse);foreach(var r in moe.GetComponentsInChildren<SkinnedMeshRenderer>(true))r.sharedMaterials=r.sharedMaterials.Select(m=>{var preview=new Material(m);preview.shader=RebirthEntityStudio.RebirthNativeShaderLibrary.Get(m.name=="HD_Moe"?"Game/Character":"Game/Autodesk");return preview;}).ToArray();foreach(var m in new[]{nurse,moe})m.GetComponent<LODGroup>().ForceLOD(0);
  if(pose)foreach(var name in new[]{"LeftArm","RightArm"}){var bone=nurse.GetComponentsInChildren<Transform>(true).Single(t=>t.name==name);bone.rotation=Quaternion.AngleAxis(name=="LeftArm"?40:-40,Vector3.forward)*bone.rotation;}
 if(side)moe.transform.position=Vector3.forward*1.5f;
 foreach(var model in new[]{nurse,moe})foreach(var skin in model.GetComponentsInChildren<SkinnedMeshRenderer>(true))if(skin.enabled&&skin.gameObject.activeInHierarchy&&(!skin.name.StartsWith("LOD")||skin.name=="LOD0")){var baked=WorldSkin(skin);var g=new GameObject("__Baked");g.AddComponent<MeshFilter>().sharedMesh=baked;g.AddComponent<MeshRenderer>().sharedMaterials=skin.sharedMaterials;skin.forceRenderingOff=true;}
 var camera=new GameObject("Camera").AddComponent<Camera>();camera.clearFlags=CameraClearFlags.SolidColor;camera.backgroundColor=new Color(.13f,.16f,.19f);camera.fieldOfView=30;camera.aspect=1.5f;camera.transform.position=new Vector3(.75f,1.05f,5.5f);camera.transform.LookAt(new Vector3(.75f,.95f,0));var light=new GameObject("Key").AddComponent<Light>();light.type=LightType.Directional;light.intensity=1.1f;light.transform.rotation=Quaternion.Euler(35,145,0);RenderSettings.ambientLight=Color.gray;
 if(side){camera.transform.position=new Vector3(5.5f,1.05f,.75f);camera.transform.LookAt(new Vector3(0,.95f,.75f));} var mat=new Material(Shader.Find("Hidden/Internal-Colored"));mat.SetInt("_ZTest",(int)CompareFunction.Always);mat.SetInt("_ZWrite",0);mat.SetInt("_Cull",0);Camera.CameraCallback callback=cam=>{if(cam!=camera)return;mat.SetPass(0);GL.PushMatrix();GL.LoadPixelMatrix(0,1500,0,1000);GL.Begin(GL.QUADS);foreach(var model in new[]{nurse,moe}){var origin=model.transform.Find("Origin");GL.Color(model==nurse?Color.cyan:new Color(.5f,1,.2f));foreach(var bone in origin.GetComponentsInChildren<Transform>(true))if(bone!=origin)Line(camera,bone.position,bone.parent.position);GL.Color(model==nurse?new Color(1,.65f,.05f):new Color(1,.35f,.12f));foreach(var cap in origin.GetComponentsInChildren<CapsuleCollider>(true))Capsule(camera,cap);}GL.End();GL.PopMatrix();};Camera.onPostRender+=callback;
 var rt=new RenderTexture(1500,1000,24);camera.targetTexture=rt;camera.Render();RenderTexture.active=rt;var texture=new Texture2D(1500,1000,TextureFormat.RGB24,false);texture.ReadPixels(new Rect(0,0,1500,1000),0,0);texture.Apply();File.WriteAllBytes(Output.Replace("Nurse_Moe_Fitted.png","Nurse_Moe_"+label+".png"),texture.EncodeToPNG());RenderTexture.active=null;Camera.onPostRender-=callback;Debug.Log("NURSE_OVERLAY_RENDERED");}catch(Exception e){Debug.LogException(e);EditorApplication.Exit(1);}}
 public static Mesh WorldSkin(SkinnedMeshRenderer skin){var source=skin.sharedMesh;var mesh=UnityEngine.Object.Instantiate(source);var vertices=source.vertices;var normals=source.normals;var tangents=source.tangents;var weights=source.boneWeights;var matrices=skin.bones.Select((b,i)=>b!=null?b.localToWorldMatrix*source.bindposes[i]:Matrix4x4.zero).ToArray();for(int i=0;i<vertices.Length;i++){var w=weights[i];int[] ids={w.boneIndex0,w.boneIndex1,w.boneIndex2,w.boneIndex3};float[] ws={w.weight0,w.weight1,w.weight2,w.weight3};Vector3 p=Vector3.zero,n=Vector3.zero,t=Vector3.zero;for(int j=0;j<4;j++){if(ws[j]<=0)continue;var m=matrices[ids[j]];p+=m.MultiplyPoint3x4(vertices[i])*ws[j];if(normals.Length>i)n+=m.MultiplyVector(normals[i])*ws[j];if(tangents.Length>i)t+=m.MultiplyVector(tangents[i])*ws[j];}vertices[i]=p;if(normals.Length>i)normals[i]=n.normalized;if(tangents.Length>i){var v=t.normalized;tangents[i]=new Vector4(v.x,v.y,v.z,tangents[i].w);}}mesh.vertices=vertices;if(normals.Length>0)mesh.normals=normals;if(tangents.Length>0)mesh.tangents=tangents;mesh.RecalculateBounds();return mesh;}
 public static void Line(Camera camera,Vector3 a,Vector3 b){Vector3 p=camera.WorldToScreenPoint(a),q=camera.WorldToScreenPoint(b);if(p.z<=0||q.z<=0)return;var d=new Vector2(q.x-p.x,q.y-p.y);if(d.sqrMagnitude<.01f)return;var n=new Vector3(-d.y,d.x,0).normalized*1.5f;p.z=0;q.z=0;GL.Vertex(p+n);GL.Vertex(p-n);GL.Vertex(q-n);GL.Vertex(q+n);}
 public static void Capsule(Camera cam,CapsuleCollider c){Vector3 axis=c.direction==0?Vector3.right:c.direction==1?Vector3.up:Vector3.forward;Vector3 u=c.direction==0?Vector3.up:Vector3.right,v=Vector3.Cross(axis,u);float h=Mathf.Max(0,c.height*.5f-c.radius);Action<Vector3,Vector3> line=(a,b)=>Line(cam,c.transform.TransformPoint(c.center+a),c.transform.TransformPoint(c.center+b));foreach(float sign in new[]{-1f,1f})for(int i=0;i<48;i++){float a=i*Mathf.PI*2/48,b=(i+1)*Mathf.PI*2/48;line(axis*h*sign+(u*Mathf.Cos(a)+v*Mathf.Sin(a))*c.radius,axis*h*sign+(u*Mathf.Cos(b)+v*Mathf.Sin(b))*c.radius);}foreach(var r in new[]{u,-u,v,-v}){line(axis*h+r*c.radius,-axis*h+r*c.radius);foreach(float sign in new[]{-1f,1f})for(int i=0;i<24;i++){float a=i*Mathf.PI/48,b=(i+1)*Mathf.PI/48;line(axis*sign*(h+c.radius*Mathf.Sin(a))+r*c.radius*Mathf.Cos(a),axis*sign*(h+c.radius*Mathf.Sin(b))+r*c.radius*Mathf.Cos(b));}}}
